cd /Users/gabe/Projects/agent-plugins
python3 - <<'EOF'
import re

versions = {
 "courier": "3.0.0", "mason": "3.0.0", "ranger": "3.0.0", "scribe": "3.0.0",
 "sentinel": "2.0.0", "navigator": "2.0.0", "smith": "2.0.0", "vanguard": "2.0.0", "weaver": "3.0.0",
}

pairs = [
 ("graph","weaver"),("trace","vanguard"),("canon","scribe"),("vector","navigator"),
 ("lambda","smith"),("proof","ranger"),("axiom","sentinel"),("delta","courier"),("basis","mason"),
]

def repl_case(new):
    def f(m):
        s = m.group(0)
        if s[0].isupper():
            return new[0].upper()+new[1:]
        return new
    return f

exclusions = {
    "plugins/smith/README.md": ["You need proof — not just a claim — that every acceptance criterion was actually tested"],
}

for plugin, ver in versions.items():
    path = f"plugins/{plugin}/README.md"
    with open(path) as f:
        content = f.read()

    # protect exclusions
    placeholders = {}
    for i, excl in enumerate(exclusions.get(path, [])):
        key = f"@@EXCL{i}@@"
        assert excl in content, (path, excl)
        content = content.replace(excl, key)
        placeholders[key] = excl

    for old, new in pairs:
        pattern = re.compile(r'\b' + old + r'\b', re.IGNORECASE)
        content = pattern.sub(repl_case(new), content)

    for key, excl in placeholders.items():
        content = content.replace(key, excl)

    # version bump
    content = re.sub(r'(\*\*Version:\*\*\s*)\d+\.\d+\.\d+', lambda m: m.group(1)+ver, content)

    with open(path, "w") as f:
        f.write(content)
    print("updated", path)
EOF
